import{_ as e,o as t,c as r,S as o}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"前端的缓存策略","description":"前端资源也需要配置缓存策略，以提高网站的访问速度。由于网站的流量增大，我们需要合适的缓存策略才能让 CDN 发挥最大效果保证网站的访问速度。","frontmatter":{"title":"前端的缓存策略","date":"2024-03-13 21:58","comments":true,"archives":2024,"tags":["web"]},"headers":[],"relativePath":"posts/2024-03-13-cache-control/index.md","filePath":"posts/2024/2024-03-13-cache-control.md"}'),n={name:"posts/2024-03-13-cache-control/index.md"};function l(s,a,c,i,h,p){return t(),r("div",null,[...a[0]||(a[0]=[o(`<p>前端资源也需要配置缓存策略，以提高网站的访问速度。由于网站的流量增大，我们需要合适的缓存策略才能让 CDN 发挥最大效果保证网站的访问速度。</p><h2 id="cache-control" tabindex="-1">Cache-Control <a class="header-anchor" href="#cache-control" aria-label="Permalink to &quot;Cache-Control&quot;">​</a></h2><p>Cache-Control 用来设置资源的缓存策略，常见的的值有：no-store 、no-cache、public、private、max-age、immutable。</p><h3 id="no-store" tabindex="-1">no-store <a class="header-anchor" href="#no-store" aria-label="Permalink to &quot;no-store&quot;">​</a></h3><p>不缓存资源，每次都需要重新请求。</p><h3 id="no-cache" tabindex="-1">no-cache <a class="header-anchor" href="#no-cache" aria-label="Permalink to &quot;no-cache&quot;">​</a></h3><p>需要先验证资源是否过期，如果没有过期，可以使用缓存。</p><h3 id="public" tabindex="-1">public <a class="header-anchor" href="#public" aria-label="Permalink to &quot;public&quot;">​</a></h3><p>资源可以被所有的用户缓存，包括 CDN。</p><h3 id="private" tabindex="-1">private <a class="header-anchor" href="#private" aria-label="Permalink to &quot;private&quot;">​</a></h3><p>资源只能被用户缓存，不能被 CDN 缓存。</p><h3 id="max-age" tabindex="-1">max-age <a class="header-anchor" href="#max-age" aria-label="Permalink to &quot;max-age&quot;">​</a></h3><p>设置资源的最大缓存时间，单位是秒。</p><h3 id="immutable" tabindex="-1">immutable <a class="header-anchor" href="#immutable" aria-label="Permalink to &quot;immutable&quot;">​</a></h3><p>资源不会改变，可以永久缓存。</p><h2 id="前端网站的缓存策略" tabindex="-1">前端网站的缓存策略 <a class="header-anchor" href="#前端网站的缓存策略" aria-label="Permalink to &quot;前端网站的缓存策略&quot;">​</a></h2><p>现在的前端网站一般都是 SPA 或者 PWA，index.html 是一个入口文件，其他的资源都是通过 index.html 加载的。所以我们可以设置 index.html 的缓存策略为 no-store，保证每次都是最新的资源。</p><p>其他的都是静态资源，并且文件名包含 hash，所以我们可以设置这些资源的缓存策略为 immutable，保证这些资源不会改变，可以永久缓存。</p><div class="language-bash line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">Cache-Control:</span><span style="color:#032F62;"> no-store</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6F42C1;">Cache-Control:</span><span style="color:#032F62;"> public,</span><span style="color:#032F62;"> max-age=604800,</span><span style="color:#032F62;"> immutable</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>index.html 文件是网站入口，这个文件不能缓存，每次都需要重新请求，否则不能及时更新网站。不过这个文件一般也不大，所以不会影响网站的访问速度。其他的静态资源文件名包含 hash，所以这些资源不会改变，可以永久缓存，这样可以提高网站的访问速度。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control" target="_blank" rel="noreferrer">MDN Cache-Control</a></p><p><a href="https://web.dev/articles/http-cache" target="_blank" rel="noreferrer">Prevent unnecessary network requests with the HTTP Cache</a></p>`,24)])])}const m=e(n,[["render",l]]);export{b as __pageData,m as default};
